'use strict';
let libraryQuery='', libraryLength='all', authMode='login', booting=true;
let accountGeneration=0, accountTransition=null, authViewGeneration=0;
window.selectedPracticeMode='practice';
const navItems=[['overview','grid','Overview'],['tests','book','Full test tickets'],['notebook','pen','Mistake notebook'],['progress','chart','My progress'],['plan','target','Study plan'],['resources','folder','Official resources']];
const names={reading:'Reading',listening:'Listening',writing:'Writing',speaking:'Speaking'};
const currentUser=()=>window.AuthUI?.user()||null;
const userName=()=>currentUser()?.user_metadata?.full_name?.split(' ')[0]||currentUser()?.email?.split('@')[0]||'Learner';
const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function streak(){const days=new Set(saved.history.map(h=>dayKey(new Date(h.date))));let n=0,d=new Date();if(!days.has(dayKey(d)))d.setDate(d.getDate()-1);while(days.has(dayKey(d))){n++;d.setDate(d.getDate()-1)}return n}
const todayMinutes=()=>saved.history.filter(h=>dayKey(new Date(h.date))===dayKey()).reduce((s,h)=>s+h.spent/60,0);
const fullQuestions=(t,record)=>questionsFor(t,record||null);
function mistakes(){const seen=new Set();let count=0;for(const h of [...saved.history].sort((a,b)=>b.date-a.date)){if(!h.total)continue;for(const q of questionsFor(h.type,h)){const key=TestLibrary.key(h)+':'+q.id;if(seen.has(key))continue;seen.add(key);if(!isCorrect(q,h.answers[q.id]))count++}}return count}
function nextSkill(){const scored=['reading','listening'].map(type=>({type,h:saved.history.find(h=>h.type===type&&h.total)}));const weak=scored.filter(x=>x.h&&x.h.score/x.h.total<.7).sort((a,b)=>a.h.score/a.h.total-b.h.score/b.h.total);if(weak.length)return weak[0].type;const last=saved.history[0]?.type;return ['reading','listening','writing','speaking'][last?(['reading','listening','writing','speaking'].indexOf(last)+1)%4:0]}
function dateCountdown(){if(!saved.examDate)return null;const d=Math.ceil((new Date(saved.examDate+'T23:59:59')-new Date())/86400000);return Math.max(0,d)}
function cleanProfile(p){const allowed=Object.keys(modules);if(!p||typeof p!=='object')p={};p.history=Array.isArray(p.history)?p.history.filter(h=>h&&allowed.includes(h.type)&&h.id&&h.answers&&Number.isFinite(h.date)&&Number.isFinite(h.spent)).slice(0,50):[];p.target=['5.0','5.5','6.0','6.5','7.0','7.5','8.0','8.5','9.0'].includes(p.target)?p.target:'7.5';p.dailyGoal=[10,20,30,45,60].includes(Number(p.dailyGoal))?Number(p.dailyGoal):20;if(p.active&&!allowed.includes(p.active.type))p.active=null;return p}
const authScope=()=>currentUser()?.id||'guest';
function accountIsCurrent(transition){return !!transition&&transition.generation===accountGeneration&&transition.scope===storageScope&&transition.scope===authScope()}
function renderAuth(){
  stopAudio();if(!window.AuthUI){page='overview';renderShell();return}
  const view=++authViewGeneration;
  $('#app').innerHTML='<main id="main">'+AuthUI.render(authMode)+'</main>';
  AuthUI.bind($('#app'),async event=>{
    // A detached form may finish after another account or page has taken over.
    if(view!==authViewGeneration||page!=='auth')return;
    if(event.type==='guest'){++authViewGeneration;try{sessionStorage.setItem('bandora-guest','yes')}catch{}page='overview';render();window.scrollTo(0,0);return}
    if(event.type==='signed-in'){
      if(!event.user?.id||event.user.id!==currentUser()?.id)return;
      const transition=await changeAccount(event.user);
      if(!accountIsCurrent(transition)||view!==authViewGeneration||page!=='auth')return;
      ++authViewGeneration;page='overview';render();window.scrollTo(0,0);toast('Welcome back. Your study space is ready.');
    }
  });
}
function changeAccount(user){
  const scope=user?.id||'guest';
  if(scope!==authScope())return Promise.resolve(null);
  // AuthUI emits SIGNED_IN before calling the form callback; both must share
  // one load. A generation also distinguishes A → B → A from the earlier A.
  if(accountTransition?.scope===scope&&storageScope===scope&&!accountTransition.stale)return accountTransition.promise;
  if(storageScope===scope&&!accountTransition?.stale)return Promise.resolve({scope,generation:accountGeneration});
  const transition={scope,generation:++accountGeneration,promise:null};
  accountTransition=transition;
  if(active)persist();clearTimeout(syncTimer);discardRecording();
  storageScope=scope;saved=cleanProfile(readStore());active=saved.active;
  if(!booting&&page!=='auth')$('#app').innerHTML='<main id="main" class="boot-screen" role="status"><p>Opening your study space…</p></main>';
  transition.promise=Promise.resolve().then(async()=>{
    if(!accountIsCurrent(transition)){transition.stale=true;return null}
    let cloud=null;
    if(user&&window.ProfileSync){try{cloud=await ProfileSync.load()}catch{}}
    if(!accountIsCurrent(transition)){transition.stale=true;return null}
    if(cloud){
      cloud=cleanProfile(cloud);
      const records=new Map([...cloud.history,...saved.history].map(h=>[h.id,h]));
      saved={...saved,...cloud,history:[...records.values()].sort((a,b)=>b.date-a.date).slice(0,50),active};
      try{localStorage.setItem(storageKey(),JSON.stringify(saved))}catch{}
    }
    if(active&&!active.paused&&remaining()<=0){page='exam';submit(true)}
    return transition;
  });
  return transition.promise;
}
async function signOut(){
  if(active){pauseActive();persist()}clearTimeout(syncTimer);discardRecording();++authViewGeneration;
  try{sessionStorage.removeItem('bandora-guest')}catch{}
  // AuthUI clears the local session immediately. Do not wait for remote token
  // revocation before changing the view, or route a later account on its return.
  const revoking=AuthUI.signOut();
  const transition=await changeAccount(null);
  if(accountIsCurrent(transition)&&!currentUser()&&page!=='auth'){authMode='login';page='auth';render()}
  await revoking;
}
function mountPracticeTools(){if(active&&!active.paused&&window.PracticeTools)PracticeTools.mount({active,questionsFor,persist,icon,storageScope,passages:active.type==='reading'?dataFor('reading').passages:undefined});}
window.mountPracticeTools=mountPracticeTools;
renderShell=function(){const user=currentUser(),label=navItems.find(n=>n[0]===page)?.[2]||'Overview';$('#app').innerHTML=`<aside class="sidebar">${brand}<span class="workspace-label">YOUR NEXT CHAPTER</span><nav aria-label="Main navigation"><div class="nav-title">YOUR WORKSPACE</div>${navItems.map(([p,i,n])=>`<button class="nav-item ${page===p?'active':''}" data-action="nav" data-page="${p}" aria-label="${n}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${n}</span>${p==='notebook'&&mistakes()?`<b class="nav-count">${mistakes()}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note"><span class="mini-orbit">${icon('spark')}</span><strong>Consistency beats intensity.</strong><p>Make a little room for your future, every day.</p><button class="text-link" data-action="nav" data-page="plan">Build your study habit ${icon('arrow')}</button></div><button class="profile row" data-work="${user?'account':'login'}"><span class="avatar">${esc(user?userName().slice(0,2).toUpperCase():'G')}</span><span><strong>${esc(user?userName():'Guest learner')}</strong><small>${user?'Account settings':'Sign in to your account'}</small></span>${icon('chevron')}</button></div></aside><div class="main-shell"><header class="topbar"><span class="breadcrumb">Your workspace <span>/</span> <strong>${label}</strong></span><div class="topbar-right"><span class="test-type"><span class="dot"></span> IELTS Academic</span><button class="header-search" data-work="search" aria-label="Search the practice library">${icon('target')}</button>${user?`<button class="avatar" data-work="account" aria-label="Account settings">${esc(userName().slice(0,2).toUpperCase())}</button>`:button('Sign in '+icon('arrow'),'nav','primary small-btn','data-page="auth"')}</div></header><main id="main">${page==='overview'?dashboard():page==='tests'?testsPage():page==='progress'?progressPage():page==='plan'?studyPlan():page==='notebook'?notebookPage():resourcesPage()}</main><footer class="footnote"><span>Bandora · Independent IELTS preparation. Original practice materials.</span><span>Practice scores are not official IELTS bands. <a href="https://ielts.org/take-a-test/test-types/ielts-academic-test" target="_blank" rel="noopener">Test format ↗</a></span></footer></div>`;if(page==='notebook')PracticeTools?.bindNotebook();};
function dashboard(){const skill=nextSkill(),goal=Number(saved.dailyGoal)||20,done=Math.floor(todayMinutes()),pct=Math.min(done/goal,1)*100,days=dateCountdown();return `<div class="workspace-heading"><div><div class="eyebrow">YOUR WORKSPACE. ALL FOUR SKILLS.</div><h1>Ready for your next step${currentUser()?', '+esc(userName()):''}?</h1><p>A clear view of your practice. A focused path to your goal.</p></div><span class="date-chip">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span></div><div class="welcome-grid"><section class="welcome-hero"><div class="hero-copy"><span class="hero-kicker"><span></span> IELTS ACADEMIC / BUILT AROUND YOU</span><h2>Go further.<br><em>One skill at a time.</em></h2><p>Connect focused practice with meaningful review. Build the skills that take you closer to your target band.</p><div class="hero-cta">${button((active?'Continue your session':'Start your practice')+' '+icon('arrow'),active?'resume':'intro','lime',active?'':`data-type="${skill}"`)}<span>${active?names[active.type]+' · '+fmt(remaining())+' left':names[skill]+' · '+modules[skill].minutes+' minutes'}</span></div></div>${journeyArt()}</section><aside class="daily-card card"><div class="row spread"><h3>Your daily intention</h3><button class="icon-button" data-work="goal" aria-label="Edit study goals">${icon('pen')}</button></div><div class="daily-ring" style="--progress:${pct}%"><div><strong>${done}<span> / ${goal}</span></strong><small>minutes today</small></div></div><p>${done>=goal?'You made time for yourself today.':'Progress starts with showing up.'}</p><div class="daily-card-footer"><span>${icon('spark')} ${streak()} day streak</span><button data-work="goal">Set a goal ${icon('chevron')}</button></div></aside></div><section class="metric-strip" aria-label="Your practice summary"><div>${icon('target')}<span><small>Target band</small><strong>${esc(saved.target)} <button data-work="goal" aria-label="Change target band">${icon('pen')}</button></strong></span></div><div>${icon('check')}<span><small>Completed sessions</small><strong>${saved.history.length}<em>one step at a time</em></strong></span></div><div>${icon('clock')}<span><small>${days===null?'Time invested':'Until test day'}</small><strong>${days===null?Math.round(saved.history.reduce((n,h)=>n+h.spent,0)/60):days}<em>${days===null?'minutes of practice':'days to prepare'}</em></strong></span></div></section>${window.TestTickets?`<section class="full-listening-notice card"><div><strong>10 complete Academic test tickets</strong><p>Every ticket includes Listening 40, Reading 40, Writing 2 tasks and Speaking 3 parts.</p></div>${button('Choose a full ticket '+icon('arrow'),'nav','primary','data-page="tests"')}</section>`:''}<section class="practice-section"><div class="section-heading"><div><div class="eyebrow muted">FOUR SKILLS. ONE AMBITION.</div><h2>What will you work on today?</h2></div><button class="text-link" data-action="nav" data-page="tests">Explore the library ${icon('arrow')}</button></div><div class="skill-grid">${skillCards()}</div></section><div class="lower-grid"><section class="card activity-card"><div class="section-heading"><div><h2>Your recent practice</h2><p class="muted">Every session tells you something.</p></div><button class="text-link" data-action="nav" data-page="progress">View all ${icon('arrow')}</button></div>${recentList()}</section><aside class="next-step-card"><span class="eyebrow">MAKE YOUR NEXT SESSION COUNT</span>${icon(mistakes()?'pen':'bulb')}<h3>${mistakes()?`${mistakes()} chances to learn something new.`:'A good review is a new beginning.'}</h3><p>${mistakes()?'Your mistake notebook brings missed answers and explanations together, so you know what to revisit.':'After your first test, revisit the answers you missed. Understanding the reason is how practice becomes progress.'}</p><button class="text-link" data-action="nav" data-page="notebook">Open mistake notebook ${icon('arrow')}</button></aside></div>`}
function journeyArt(){return window.BandoraArtwork(saved.target,'YOUR TARGET BAND')}
function skillCards(){return Object.entries(modules).map(([t,m],i)=>`<article class="skill-card skill-${t}"><div class="skill-card-top"><span class="skill-number">0${i+1}</span><span class="skill-badge">${m.label==='FULL SECTION'?'Full section':t==='listening'?'10-minute focus':'Guided session'}</span></div><div class="skill-art">${skillArt(t)}</div><h3>${names[t]}</h3><p>${t==='reading'?'Read between the lines.':t==='listening'?'Catch the little details.':t==='writing'?'Give your ideas a voice.':'Find your speaking rhythm.'}</p><div class="skill-details"><span>${icon('clock')} ${m.minutes} min</span><span>${m.count}</span></div><button class="skill-start" data-action="intro" data-type="${t}"><span>Practise ${t}</span>${icon('arrow')}</button></article>`).join('')}
function skillArt(t){const paths={reading:'<path d="M20 23q15-5 30 3v44q-15-8-30-3zm30 3q15-8 30-3v44q-15-5-30 3z" fill="currentColor" opacity=".15"/><path d="M20 23q15-5 30 3v44q-15-8-30-3zm30 3q15-8 30-3v44q-15-5-30 3zM29 34l12 3m-12 7 12 3m-12 7 12 3m18-20 12-3m-12 13 12-3m-12 13 12-3" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/>',listening:'<path d="M25 51V39a25 25 0 0 1 50 0v12" stroke="currentColor" stroke-width="6"/><rect x="18" y="44" width="15" height="27" rx="6" fill="currentColor"/><rect x="67" y="44" width="15" height="27" rx="6" fill="currentColor"/><path d="M42 45v12m8-18v24m8-18v12" stroke="currentColor" stroke-width="3" stroke-linecap="round"/>',writing:'<rect x="24" y="16" width="45" height="61" rx="5" fill="currentColor" opacity=".12"/><path d="M34 31h24M34 42h15M34 53h8" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><path d="m47 67 5-13 24-24 8 8-24 24zm24-32 8 8" stroke="currentColor" stroke-width="2.8" stroke-linejoin="round"/><path d="m47 67 13-5-8-8z" fill="currentColor"/>',speaking:'<rect x="40" y="14" width="20" height="41" rx="10" fill="currentColor" opacity=".2" stroke="currentColor" stroke-width="3"/><path d="M30 42v5a20 20 0 0 0 40 0v-5M50 67v12m-12 0h24M44 28h12m-12 8h12" stroke="currentColor" stroke-width="2.8" stroke-linecap="round"/>'};return `<svg viewBox="0 0 100 90" fill="none" aria-hidden="true">${paths[t]}</svg>`}
function recentList(){if(!saved.history.length)return `<div class="welcome-empty"><span>${icon('book')}</span><div><h3>A blank page full of possibilities.</h3><p>Your completed practice will appear here. Start with the skill you’d like to understand better.</p><button class="text-link" data-action="intro" data-type="reading">Take your first Reading mock ${icon('arrow')}</button></div></div>`;return saved.history.slice(0,3).map(h=>`<button class="recent-row" data-action="review" data-id="${h.id}"><span class="test-icon ${h.type}">${icon(modules[h.type].icon)}</span><span><strong>${esc(dataFor(h.type,h).title)}</strong><small>${dateLabel(h.date)} · ${h.mode==='exam'?'Exam mode':'Practice mode'}</small></span><b>${h.total?h.score+'/'+h.total:'Self-review'}</b>${icon('chevron')}</button>`).join('')}
cards=function(){const entries=TestLibrary.sets.map(s=>[s.type,{...modules[s.type],...s,desc:s.description,footer:s.footer||(s.type==='reading'?s.data.passages.length+' original passage'+(s.data.passages.length>1?'s':''):modules[s.type].footer)}]).filter(([t,m])=>(filter==='all'||filter===t)&&(!libraryQuery||`${t} ${m.title} ${m.desc}`.toLowerCase().includes(libraryQuery.toLowerCase()))&&(libraryLength==='all'||(libraryLength==='short'?m.minutes<=20:m.minutes>20)));return entries.length?entries.map(([t,m])=>`<article class="library-card card"><div class="library-art skill-${t}">${skillArt(t)}<span class="eyebrow">${m.label}</span></div><div class="library-card-body"><span class="eyebrow muted">BANDORA ORIGINAL · ${m.id.split('-')[1]}</span><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p><div class="library-meta"><span>${icon('clock')} ${m.minutes} minutes</span><span>${m.count}</span><span>${m.footer}</span></div><div class="row spread"><span class="tag green">${saved.history.some(h=>TestLibrary.key(h)===m.id)?'Practised before':'Ready to start'}</span>${button('Start session '+icon('arrow'),'intro','primary small-btn',`data-type="${t}" data-set="${m.id}"`)}</div></div></article>`).join(''):`<div class="card empty full-span"><h3>No sessions match your search.</h3><p>Try a skill name, or clear the filters.</p><button class="btn secondary" data-work="clear-filters">Clear filters</button></div>`};
testsPage=function(){return `<div class="workspace-heading"><div><div class="eyebrow">PURPOSEFUL PRACTICE</div><h1>Your practice library.</h1><p>${TestLibrary.sets.length} original sessions. Choose a skill, a topic, and your pace.</p></div></div>${active?`<div class="resume-strip card"><span class="resume-pulse"></span><div><strong>A session is waiting for you</strong><p>${names[active.type]} · ${active.mode==='exam'?'Exam timer is running':active.paused?'Paused':'In progress'} · ${fmt(remaining())} remaining</p></div>${button('Continue '+icon('arrow'),'resume','primary small-btn')}</div>`:''}<div class="library-controls"><label class="library-search"><span>${icon('target')}</span><input id="library-query" type="search" value="${esc(libraryQuery)}" placeholder="Search a skill or practice…" aria-label="Search practices"></label><label class="duration-filter">Duration <select id="library-length"><option value="all" ${libraryLength==='all'?'selected':''}>Any length</option><option value="short" ${libraryLength==='short'?'selected':''}>20 minutes or less</option><option value="full" ${libraryLength==='full'?'selected':''}>Full-length sections</option></select></label></div>${filterBar()}<div class="library-grid" id="library-results">${cards()}</div><div class="library-note">${icon('bulb')}<p>Choose a full Reading section or a focused passage. Listening includes a 40-question mock and shorter exercises, all with browser-generated audio; Speaking is self-guided. All on-site questions are Bandora originals. <button class="text-link" data-action="nav" data-page="resources">Find official Cambridge English, IELTS and British Council samples ↗</button></p></div>`};
const studyGuidesPage=resourcesPage;
resourcesPage=function(){return `<div class="workspace-heading"><div><div class="eyebrow">GO TO THE SOURCE</div><h1>Official resources. More ways to practise.</h1><p>Explore Cambridge English, IELTS and British Council materials alongside your Bandora sessions.</p></div></div><div class="official-intro card"><div>${icon('globe')}<strong>Official materials open on the provider’s website.</strong><p>Use the samples and answer keys there. External practice is not scored or saved in Bandora. Our on-site exercises are original and are not official Cambridge or IELTS tests.</p></div><button class="btn secondary" data-action="nav" data-page="tests">Practise in Bandora ${icon('arrow')}</button></div><section class="official-grid" aria-label="Official IELTS preparation resources">${OfficialResources.map(r=>`<article class="official-card card"><div class="eyebrow">${esc(r.provider)} · EXTERNAL RESOURCE</div><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><span class="small muted">${esc(r.skills)}</span><a class="btn primary" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Visit ${esc(r.provider)} <span aria-hidden="true">↗</span><span class="sr-only"> (opens in a new tab)</span></a></article>`).join('')}</section><p class="small muted resource-checked">Links checked 20 October 2026. Availability and access are managed by each provider. Bandora is independent of these organisations.</p>${studyGuidesPage().replace('<h1>A little guidance goes a long way.</h1>','<h2>Make your next practice more useful.</h2>')}`};
function notebookPage(){return window.PracticeTools?PracticeTools.reviewNotebookHTML({history:saved.history,questionsFor:fullQuestions,storageScope,isCorrect}):'<div class="workspace-heading"><div><h1>Your mistake notebook</h1><p>Complete a Reading or Listening session to start your notebook.</p></div></div>'}
function performanceChart(){const points=saved.history.filter(h=>h.total).slice(0,8).reverse();if(!points.length)return `<div class="chart-placeholder">${icon('chart')}<h3>Your progress will have a shape.</h3><p>Finish a Reading or Listening session to see your accuracy here.</p></div>`;const x=i=>points.length===1?300:50+i*500/(points.length-1),y=h=>170-h.score/h.total*140;return `<div class="accuracy-chart"><svg viewBox="0 0 600 215" role="img" aria-label="Accuracy of your last ${points.length} scored sessions">${[0,50,100].map(n=>`<path d="M42 ${170-n*1.4}H570" stroke="#e7ebe3" stroke-dasharray="4 5"/><text x="6" y="${175-n*1.4}" fill="#7c8779" font-size="11">${n}%</text>`).join('')}<polyline fill="none" stroke="#4b7652" stroke-width="3" points="${points.map((h,i)=>`${x(i)},${y(h)}`).join(' ')}"/>${points.map((h,i)=>`<circle cx="${x(i)}" cy="${y(h)}" r="6" fill="${h.type==='reading'?'#456e4b':'#7780bb'}" stroke="white" stroke-width="3"/><text x="${x(i)}" y="202" text-anchor="middle" fill="#7c8779" font-size="11">${dateLabel(h.date)}</text><title>${names[h.type]}: ${Math.round(h.score/h.total*100)}%</title>`).join('')}</svg><div class="chart-caption"><span><i></i> Reading</span><span><i></i> Listening</span><small>Practice accuracy, not a band prediction.</small></div></div>`}
function questionBreakdown(){const rows={tfng:{label:'True / False / Not given',correct:0,total:0},mcq:{label:'Multiple choice',correct:0,total:0},text:{label:'Short answers',correct:0,total:0}};const seen=new Set();for(const h of saved.history){for(const q of questionsFor(h.type,h)){if(seen.has(TestLibrary.key(h)+':'+q.id))continue;seen.add(TestLibrary.key(h)+':'+q.id);if(!rows[q.type]){if(!window.IELTSFormats)continue;rows[q.type]={label:IELTSFormats.typeLabel(q),correct:0,total:0}}rows[q.type].total++;if(isCorrect(q,h.answers[q.id]))rows[q.type].correct++}}return `<div class="breakdown-list">${Object.values(rows).map(r=>`<div><div class="row spread"><span>${r.label}</span><strong>${r.total?Math.round(r.correct/r.total*100)+'%':'—'}</strong></div><div class="breakdown-track"><i style="width:${r.total?r.correct/r.total*100:0}%"></i></div><small>${r.total?r.correct+' of '+r.total+' correct on latest attempts':'No completed questions yet'}</small></div>`).join('')}</div>`}
progressPage=function(){const total=Math.round(saved.history.reduce((n,h)=>n+h.spent,0)/60);return `<div class="workspace-heading"><div><div class="eyebrow">SEE THE BIGGER PICTURE</div><h1>Your effort is adding up.</h1><p>Real practice. Useful patterns. A clearer next step.</p></div>${saved.history.length?button(icon('download')+' Export results','export','secondary'):''}</div><div class="progress-stats"><article class="card"><span>${icon('check')}</span><small>Sessions completed</small><strong>${saved.history.length}</strong></article><article class="card"><span>${icon('clock')}</span><small>Minutes invested</small><strong>${total}</strong></article><article class="card"><span>${icon('spark')}</span><small>Current streak</small><strong>${streak()} <em>days</em></strong></article><article class="card"><span>${icon('target')}</span><small>Your target band</small><strong>${saved.target}</strong></article></div><div class="analytics-grid"><section class="card analytics-card"><div class="section-heading"><h2>Accuracy over time</h2><span class="tag">Last 8 scored sessions</span></div>${performanceChart()}</section><section class="card analytics-card"><h2>Where to focus next</h2><p class="muted small">Latest attempt per question</p>${questionBreakdown()}</section></div><section class="card history-section"><div class="section-heading"><h2>Your practice history</h2><span class="muted small">${saved.history.length} sessions</span></div>${historyHTML()}</section>`};
function studyPlan(){const dayLabels=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],skills=['reading','listening','writing','speaking','reading','listening','review'];const today=(new Date().getDay()+6)%7;const days=dateCountdown();return `<div class="workspace-heading"><div><div class="eyebrow">A LITTLE STRUCTURE. A LOT OF POSSIBILITY.</div><h1>Make space for your goal.</h1><p>A flexible weekly rhythm. Start wherever you are.</p></div><button class="btn secondary" data-work="goal">${icon('pen')} Edit your goals</button></div><div class="plan-summary card"><div><small>YOUR TARGET BAND</small><strong>${saved.target}</strong></div><div><small>DAILY INTENTION</small><strong>${saved.dailyGoal||20}<span>minutes</span></strong></div><div><small>YOUR TEST DATE</small><strong>${saved.examDate?new Date(saved.examDate+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'short'}):'Your pace'}<span>${days===null?'Set a date when you’re ready':days+' days to prepare'}</span></strong></div></div><div class="plan-week">${dayLabels.map((day,i)=>{const t=skills[i];return `<article class="plan-day card ${i===today?'today':''}"><div><span class="eyebrow">${day}</span>${i===today?'<span class="tag green">Today</span>':''}</div><span class="test-icon ${t}">${icon(t==='review'?'pen':modules[t].icon)}</span><h3>${t==='review'?'Reflect & review':names[t]+' focus'}</h3><p>${t==='review'?'Return to your notebook and review what you learned this week.':t==='writing'?'Work on a clear overview or a well-supported argument.':t==='speaking'?'Speak aloud, record a response, then listen back.':t==='reading'?'Read for meaning and find the evidence behind each answer.':'Listen for details, then check the transcript in your review.'}</p><span class="muted small">${saved.dailyGoal||20} minute focus block</span><button class="text-link" data-action="${t==='review'?'nav':'intro'}" ${t==='review'?'data-page="notebook"':`data-type="${t}"`}>${t==='review'?'Open notebook':'Start practice'} ${icon('arrow')}</button></article>`}).join('')}</div><p class="plan-explainer">Your daily intention is a study target. Full Reading and Writing sections keep their 60-minute timers; use practice mode to pause between focus blocks.</p>`}
function goalDialog(){modal('Make the goal yours.',`<p>Set an intention that fits your life. You can change it whenever you need to.</p><form id="goals-form" class="goals-form"><label>Target band<select name="target">${['5.0','5.5','6.0','6.5','7.0','7.5','8.0','8.5','9.0'].map(x=>`<option ${saved.target===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Daily practice<select name="dailyGoal">${[10,20,30,45,60].map(x=>`<option value="${x}" ${Number(saved.dailyGoal||20)===x?'selected':''}>${x} minutes</option>`).join('')}</select></label><label class="full-span">Test date <span class="muted">(optional)</span><input type="date" name="examDate" min="${dayKey()}" value="${esc(saved.examDate||'')}"></label></form>`,button('Cancel','close','secondary')+'<button class="btn primary" data-work="save-goals">Save my goals</button>')}
intro=function(type,setId,mode='practice'){window.selectedPracticeMode=mode==='exam'?'exam':'practice';const chosen=TestLibrary.get(type,setId||(window.TestTickets?type+'-101':type==='listening'?'listening-04':undefined)),m={...modules[type],...chosen},note=chosen.description;modal(esc(m.title),`<p>${esc(note)}</p><p class="small muted">Bandora original · Independent practice${type==='listening'?' · Browser-generated audio':''}</p><div class="session-facts"><span>${icon('clock')} ${m.minutes} minutes</span><span>${m.count}</span></div><fieldset class="mode-picker"><legend>Choose your pace</legend><label><input type="radio" name="practice-mode" value="practice" ${window.selectedPracticeMode==='practice'?'checked':''}><span><strong>Practice mode</strong><small>Pause, make notes, and work at your pace.</small></span></label><label><input type="radio" name="practice-mode" value="exam" ${window.selectedPracticeMode==='exam'?'checked':''}><span><strong>Exam mode</strong><small>Timer keeps running. ${type==='listening'?'Each part plays once.':'No pauses until you submit.'}</small></span></label></fieldset>${active?'<p class="replace-note">Starting replaces your unfinished session. Your completed results are kept.</p>':''}`,button('Not now','close','secondary')+button('Begin session '+icon('arrow'),'start','primary',`data-type="${type}" data-set="${chosen.id}"`))};
function mountResultTools(){const h=saved.history.find(h=>h.id===resultId);if(!h?.total)return;const review=$('.result-review');if(!review||$('.review-filters'))return;const bar=document.createElement('div');bar.className='review-filters';bar.innerHTML=`<div class="filters"><button class="filter active" data-review-filter="all">All answers</button><button class="filter" data-review-filter="incorrect">Needs review (${h.total-h.score})</button><button class="filter" data-review-filter="correct">Correct (${h.score})</button></div><button class="btn secondary small-btn" data-work="result-notebook">Open mistake notebook ${icon('arrow')}</button>`;review.insertBefore(bar,review.querySelector('.review-item'));}
function accountDialog(){const user=currentUser();if(!user){authMode='login';go('auth');return}modal('Your study account',`<p>Signed in as <strong>${esc(user.email)}</strong></p><div class="dialog-details">${esc(window.ProfileSync?.status()||'Saved on this browser')}<br>Unfinished sessions and recordings stay on this device.</div>`,button('Close','close','secondary')+'<button class="btn primary" data-work="signout">Sign out</button>')}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-work]');if(b){e.preventDefault();switch(b.dataset.work){case'login':authMode='login';go('auth');break;case'account':accountDialog();break;case'signout':closeModal();await signOut();break;case'goal':goalDialog();break;case'save-goals':{const form=$('#goals-form');if(!form.reportValidity())return;const values=new FormData(form);saved.target=values.get('target');saved.dailyGoal=Number(values.get('dailyGoal'));saved.examDate=values.get('examDate')||null;persist();closeModal();render();toast('Your goals are saved. One step at a time.');break}case'clear-filters':filter='all';libraryQuery='';libraryLength='all';renderShell();break;case'search':go('tests');($('#ticket-query')||$('#library-query'))?.focus();break;case'result-notebook':go('notebook');break}}const f=e.target.closest('[data-review-filter]');if(f){document.querySelectorAll('[data-review-filter]').forEach(x=>x.classList.toggle('active',x===f));document.querySelectorAll('.result-review .review-item').forEach(item=>item.hidden=f.dataset.reviewFilter!=='all'&&!item.querySelector('.row > strong.'+f.dataset.reviewFilter));}});
document.addEventListener('input',e=>{if(e.target.id==='library-query'){libraryQuery=e.target.value;$('#library-results').innerHTML=cards()}});
document.addEventListener('change',e=>{if(e.target.id==='library-length'){libraryLength=e.target.value;$('#library-results').innerHTML=cards()}if(e.target.name==='practice-mode')window.selectedPracticeMode=e.target.value});
window.addEventListener('bandly:auth-change',async()=>{
  if(booting)return;
  const user=currentUser();
  if((user?.id||'guest')===storageScope)return;
  const transition=await changeAccount(user);
  if(!accountIsCurrent(transition))return;
  if(!user){++authViewGeneration;page='auth';authMode='login';render()}
  // The active auth form owns its successful navigation; rerendering it here
  // would detach that callback while the shared profile load is completing.
  else if(page!=='auth')render();
});
async function boot(){
  saved=cleanProfile(saved);$('#app').innerHTML='<div class="boot-screen"><span class="brand-mark"><i></i><i></i><i></i></span><p>Making room for your next chapter…</p></div>';
  let result={};
  try{
    result=await AuthUI.init();
    // Auth changes during boot are reconciled here, including one that occurs
    // while a previous account's cloud load is pending.
    while(!accountIsCurrent(await changeAccount(currentUser()))){}
  }catch{toast('Your account could not be restored. You can continue as a guest.')}
  booting=false;let guest=false;try{guest=sessionStorage.getItem('bandora-guest')==='yes'}catch{}
  const modeApplies=result.mode&&(result.user?result.user.id===currentUser()?.id:!currentUser());
  if(modeApplies){authMode=result.mode;page='auth'}else if(currentUser()||guest){page=active?'exam':'overview'}else page='auth';
  if(active&&!active.paused&&remaining()<=0){submit(true)}else render();
}
boot();
